// Validate incoming passive WiFi capture packets
const payload = msg.payload || {};
const packetSource = Array.isArray(payload.packets) ? payload.packets : (Array.isArray(payload.devices) ? payload.devices : []);

if (packetSource.length === 0) {
    node.warn("No WiFi capture packets received");
    return null;
}

const macPattern = /^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$/;

function channelToFrequency(channel) {
    if (channel >= 1 && channel <= 13) return 2407 + channel * 5;
    if (channel === 14) return 2484;
    return 0;
}

function normalizeFrameType(value) {
    const frameType = String(value || "management").toLowerCase();
    if (frameType === "probe_request") return "probe_req";
    if (frameType === "probe_response") return "probe_resp";
    if (["probe_req", "probe_resp", "beacon", "management"].includes(frameType)) return frameType;
    return "management";
}

let validatedDevices = [];
for (const packet of packetSource) {
    const mac = packet.source_mac || packet.mac || packet.mac_address || packet.sa;
    if (!mac || typeof mac !== "string" || !macPattern.test(mac)) continue;

    const normalizedMac = mac.toUpperCase().replace(/-/g, ":");
    const channel = Number.parseInt(packet.channel, 10) || 0;
    const frequency = Number.parseInt(packet.frequency, 10) || channelToFrequency(channel) || 2412;
    const rssi = Number.parseInt(packet.rssi, 10);
    const seenCount = Number.parseInt(packet.seen_count, 10);

    validatedDevices.push({
        mac: normalizedMac,
        source_mac: normalizedMac,
        ssid: packet.ssid || "",
        rssi: Number.isFinite(rssi) ? rssi : -80,
        frequency,
        channel,
        frame_type: normalizeFrameType(packet.frame_type || packet.subtype),
        seen_count: Number.isFinite(seenCount) && seenCount > 0 ? seenCount : 1
    });
}

if (validatedDevices.length === 0) {
    node.warn("No valid MAC addresses in capture");
    return null;
}

msg.payload = {
    device_id: payload.device_id,
    timestamp: payload.timestamp || new Date().toISOString(),
    devices: validatedDevices
};

return msg;

const payload = msg.payload || {};
const event = String(payload.event || "").toLowerCase();

if (!["entrada", "saida"].includes(event)) {
    node.warn("Invalid event payload");
    return null;
}

msg.payload = {
    device_id: payload.device_id || "esp8266_001",
    event,
    ts: payload.ts || Date.now()
};

return msg;
